// 2. STATE MANAGEMENT
const STORAGE_KEY_COMPANIES = 'ejm_audit_companies_v1';
const STORAGE_KEY_SCRIPT_URL = 'ejm_audit_apps_script_url_v1';

// GitHub'ga joylashdan oldin Apps Script Web App URL'ini shu yerga yozing —
// shunda saytni ochgan har bir qurilmada Google Sheets avtomatik ulangan bo'ladi.
const DEFAULT_APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxFwfWdhNpMZhbZElH1nfXzWhBRlw8I6tdpqHgC7F7wTjDguu9JKy8iQqDDxobNJ0Ny/exec';

let companies = [];
let currentCompanyId = null;
let activeStageId = 'stage_1';
let questionFilter = 'ALL';

// Initialize Application
window.onload = function () {
  try {
    const savedCompanies = localStorage.getItem(STORAGE_KEY_COMPANIES);
    if (savedCompanies) {
      companies = JSON.parse(savedCompanies);
    }
  } catch (e) {
    console.error('Storage load error:', e);
  }

  // Set default date in modal to today
  const todayStr = new Date().toISOString().split('T')[0];
  document.getElementById('inpAuditDate').value = todayStr;

  updateConnectionStatusUI();
  showView('companies');
  refreshRemoteCompanies();
};

// ---- Backend bilan aloqa ----
async function apiCall(body) {
  const response = await fetch(getAppsScriptUrl(), {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify(body)
  });
  return response.json();
}

function getAppsScriptUrl() {
  let saved = '';
  try { saved = localStorage.getItem(STORAGE_KEY_SCRIPT_URL) || ''; } catch (e) { /* storage yo'q */ }
  return (saved || DEFAULT_APPS_SCRIPT_URL).trim();
}

function saveCompaniesToStorage() {
  try {
    localStorage.setItem(STORAGE_KEY_COMPANIES, JSON.stringify(companies));
  } catch (e) {
    console.error('Storage save error:', e);
  }
}

function updateConnectionStatusUI() {
  const url = getAppsScriptUrl();
  const badge = document.getElementById('connectionBadge');
  const alertBanner = document.getElementById('setupAlertBanner');

  if (url) {
    badge.className = 'inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200';
    badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>Google Sheets ulangan';
    if (alertBanner) alertBanner.classList.add('hidden');
  } else {
    badge.className = 'inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200';
    badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-amber-500"></span>Demo rejim';
    if (alertBanner) alertBanner.classList.remove('hidden');
  }
}

// 3. TOAST NOTIFICATIONS
function showToast(message, type = 'info') {
  const container = document.getElementById('toastContainer');
  const toast = document.createElement('div');
  const colors = {
    success: 'bg-slate-900 text-white border-emerald-500',
    error: 'bg-rose-600 text-white border-rose-800',
    info: 'bg-slate-800 text-white border-brand-500'
  };
  toast.className = `pointer-events-auto flex items-center gap-2.5 px-4 py-3 rounded-xl shadow-lg border-l-4 text-xs sm:text-sm font-medium transition-all duration-300 ${colors[type] || colors.info}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(8px)';
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// 4. SCORING & CALCULATIONS (Matches Natija Sheet Logic: HA = 1, QISMAN = 0.5, YO'Q = 0)
function calculateCompanyStats(company) {
  let totalQuestions = 0;
  let totalAnswered = 0;
  let totalPoints = 0;
  let countHa = 0;
  let countQisman = 0;
  let countYoq = 0;

  const stageStats = EJM_TEMPLATE.map(stage => {
    let sTotal = 0;
    let sAnswered = 0;
    let sPoints = 0;

    stage.blocks.forEach(block => {
      block.questions.forEach(q => {
        sTotal++;
        totalQuestions++;
        const ansObj = company.answers[q.code];
        if (ansObj && ansObj.answer) {
          sAnswered++;
          totalAnswered++;
          if (ansObj.answer === 'HA') {
            sPoints += 1;
            totalPoints += 1;
            countHa++;
          } else if (ansObj.answer === 'QISMAN') {
            sPoints += 0.5;
            totalPoints += 0.5;
            countQisman++;
          } else if (ansObj.answer === "YO'Q") {
            countYoq++;
          }
        }
      });
    });

    const scorePct = sTotal > 0 ? Math.round((sPoints / sTotal) * 100) : 0;
    const completionPct = sTotal > 0 ? Math.round((sAnswered / sTotal) * 100) : 0;

    return {
      id: stage.id,
      sheetName: stage.sheetName,
      shortName: stage.shortName,
      title: stage.title,
      total: sTotal,
      answered: sAnswered,
      points: sPoints,
      scorePct,
      completionPct
    };
  });

  const overallScorePct = totalQuestions > 0 ? Math.round((totalPoints / totalQuestions) * 100) : 0;
  const overallCompletionPct = totalQuestions > 0 ? Math.round((totalAnswered / totalQuestions) * 100) : 0;

  let levelLabel = "Boshlang'ich (Tizimsiz)";
  if (overallScorePct >= 80) levelLabel = "Yuqori (Tizimlashgan)";
  else if (overallScorePct >= 50) levelLabel = "O'rta (Rivojlanayotgan)";
  else if (overallScorePct >= 25) levelLabel = "Past (Bazaviy)";

  return {
    totalQuestions,
    totalAnswered,
    totalPoints,
    countHa,
    countQisman,
    countYoq,
    overallScorePct,
    overallCompletionPct,
    levelLabel,
    stageStats
  };
}

