function updateWorkspaceStatusBadge(company) {
  const badge = document.getElementById('wsStatusBadge');
  if (company.status === 'completed') {
    badge.className = 'px-2.5 py-0.5 rounded-lg text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200';
    badge.textContent = 'Yakunlangan';
  } else {
    badge.className = 'px-2.5 py-0.5 rounded-lg text-xs font-semibold bg-blue-50 text-blue-700 border border-blue-200';
    badge.textContent = 'Jarayonda';
  }
}

function renderWorkspaceKPIs() {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;

  const stats = calculateCompanyStats(company);
  document.getElementById('kpiOverallScore').textContent = stats.overallScorePct + '%';
  document.getElementById('kpiOverallLabel').textContent = stats.levelLabel;
  document.getElementById('kpiOverallBar').style.width = stats.overallScorePct + '%';

  document.getElementById('kpiCompletionPct').textContent = stats.overallCompletionPct + '%';
  document.getElementById('kpiAnsweredCount').textContent = `${stats.totalAnswered} / ${stats.totalQuestions} savol`;
  document.getElementById('kpiCompletionBar').style.width = stats.overallCompletionPct + '%';

  document.getElementById('kpiCountHa').textContent = stats.countHa;
  document.getElementById('kpiCountQisman').textContent = stats.countQisman;
  document.getElementById('kpiCountYoq').textContent = stats.countYoq;

  const currentStageStat = stats.stageStats.find(s => s.id === activeStageId) || stats.stageStats[0];
  document.getElementById('kpiStageScore').textContent = currentStageStat.scorePct + '%';
  document.getElementById('kpiStageName').textContent = currentStageStat.shortName;
  document.getElementById('kpiStageBar').style.width = currentStageStat.scorePct + '%';
}

function renderStageTabs() {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;
  const stats = calculateCompanyStats(company);
  const container = document.getElementById('stageTabsContainer');

  container.innerHTML = stats.stageStats.map(s => {
    const isActive = s.id === activeStageId;
    const activeClasses = isActive
      ? 'bg-brand-600 text-white border-brand-600 shadow-sm'
      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50';
    const pillClasses = isActive
      ? 'bg-white/20 text-white'
      : 'bg-slate-100 text-slate-600';

    return `
      <button onclick="selectStage('${s.id}')"
              class="shrink-0 flex items-center gap-2 px-4 py-2.5 rounded-xl border text-xs sm:text-sm font-bold transition ${activeClasses}">
        <span>${s.shortName}</span>
        <span class="px-2 py-0.5 rounded-md text-[11px] font-extrabold ${pillClasses}">${s.scorePct}%</span>
      </button>
    `;
  }).join('');
}

function selectStage(stageId) {
  activeStageId = stageId;
  renderWorkspaceKPIs();
  renderStageTabs();
  renderQuestionsArea();
}

function setQuestionFilter(filterType) {
  questionFilter = filterType;
  document.querySelectorAll('.q-filter-btn').forEach(btn => {
    if (btn.dataset.filter === filterType) {
      btn.className = 'q-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-brand-600 text-white';
    } else {
      btn.className = 'q-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200';
    }
  });
  renderQuestionsArea();
}

function renderQuestionsArea() {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;

  const stage = EJM_TEMPLATE.find(s => s.id === activeStageId);
  const container = document.getElementById('blocksContainer');
  const searchQuery = (document.getElementById('questionSearchInput').value || '').toLowerCase().trim();

  let html = '';

  stage.blocks.forEach(block => {
    const filteredQuestions = block.questions.filter(q => {
      const ansObj = company.answers[q.code] || {};
      if (searchQuery && !q.text.toLowerCase().includes(searchQuery) && !q.code.includes(searchQuery)) {
        return false;
      }
      if (questionFilter === 'UNANSWERED' && ansObj.answer) return false;
      if (questionFilter === 'GAPS' && ansObj.answer !== "YO'Q" && ansObj.answer !== 'QISMAN') return false;
      return true;
    });

    if (filteredQuestions.length === 0) return;

    // Calculate block score
    let bPoints = 0;
    block.questions.forEach(q => {
      const a = company.answers[q.code]?.answer;
      if (a === 'HA') bPoints += 1;
      else if (a === 'QISMAN') bPoints += 0.5;
    });
    const blockPct = Math.round((bPoints / block.questions.length) * 100);

    html += `
      <div class="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
        <div class="px-5 py-3.5 bg-slate-50 border-b border-slate-200 flex items-center justify-between gap-3">
          <h3 class="text-sm sm:text-base font-extrabold text-slate-900">${escapeHtml(block.title)}</h3>
          <span class="px-2.5 py-1 rounded-lg text-xs font-bold bg-white border border-slate-200 text-slate-700">
            Blok natijasi: <span class="text-brand-600">${blockPct}%</span>
          </span>
        </div>

        <div class="divide-y divide-slate-100">
          ${filteredQuestions.map(q => renderQuestionRow(company, q)).join('')}
        </div>
      </div>
    `;
  });

  if (!html) {
    html = `
      <div class="bg-white rounded-2xl border border-slate-200 p-8 text-center text-sm text-slate-500">
        Tanlangan filtr bo'yicha ushbu bo'limda savollar topilmadi.
      </div>
    `;
  }

  container.innerHTML = html;
}

function renderQuestionRow(company, q) {
  const data = company.answers[q.code] || {
    answer: '',
    link: '',
    responsible: '',
    practice: '',
    video: '',
    comment: ''
  };

  const haClass = data.answer === 'HA'
    ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm'
    : 'bg-white text-slate-700 border-slate-200 hover:bg-emerald-50';
  const qismanClass = data.answer === 'QISMAN'
    ? 'bg-amber-500 text-white border-amber-500 shadow-sm'
    : 'bg-white text-slate-700 border-slate-200 hover:bg-amber-50';
  const yoqClass = data.answer === "YO'Q"
    ? 'bg-rose-600 text-white border-rose-600 shadow-sm'
    : 'bg-white text-slate-700 border-slate-200 hover:bg-rose-50';

  return `
    <div id="q-${q.code}" class="p-4 sm:p-5 space-y-3.5 hover:bg-slate-50/50 transition">
      <div class="flex flex-col lg:flex-row lg:items-center justify-between gap-3">
        <div class="flex items-start gap-2.5 max-w-3xl">
          <span class="px-2 py-0.5 rounded-md bg-slate-100 text-slate-600 font-mono text-xs font-bold shrink-0 mt-0.5">${q.code}</span>
          <div>
            <p class="text-sm font-semibold text-slate-800 leading-snug">${escapeHtml(q.text)}</p>
            ${stepChipsFor(q.code)}
          </div>
        </div>

        <!-- HA / QISMAN / YO'Q Buttons -->
        <div class="flex items-center gap-2 shrink-0">
          <button type="button" onclick="setQuestionAnswer('${q.code}', 'HA')"
                  class="answer-btn px-3.5 py-2 rounded-xl border text-xs font-extrabold ${haClass}">
            HA (1)
          </button>
          <button type="button" onclick="setQuestionAnswer('${q.code}', 'QISMAN')"
                  class="answer-btn px-3.5 py-2 rounded-xl border text-xs font-extrabold ${qismanClass}">
            QISMAN (0.5)
          </button>
          <button type="button" onclick="setQuestionAnswer('${q.code}', &quot;YO'Q&quot;)"
                  class="answer-btn px-3.5 py-2 rounded-xl border text-xs font-extrabold ${yoqClass}">
            YO'Q (0)
          </button>
        </div>
      </div>

      <!-- Exact Spreadsheet Extra Columns (Instrument Link, Mas'ul shaxs, Amaliyot %, Video darslik, Izoh) -->
      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-12 gap-2.5 pt-1">
        <div class="lg:col-span-3">
          <input type="text" value="${escapeHtml(data.link || '')}"
                 onchange="updateQuestionField('${q.code}', 'link', this.value)"
                 placeholder="Instrument Link (URL / Hujjat)"
                 class="w-full px-3 py-1.5 rounded-lg border border-slate-200 bg-white text-xs focus:outline-none focus:ring-2 focus:ring-brand-500" />
        </div>

        <div class="lg:col-span-2">
          <input type="text" value="${escapeHtml(data.responsible || '')}"
                 onchange="updateQuestionField('${q.code}', 'responsible', this.value)"
                 placeholder="Mas'ul shaxs"
                 class="w-full px-3 py-1.5 rounded-lg border border-slate-200 bg-white text-xs focus:outline-none focus:ring-2 focus:ring-brand-500" />
        </div>

        <div class="lg:col-span-2">
          <div class="relative">
            <input type="number" min="0" max="100" value="${escapeHtml(data.practice || '')}"
                   onchange="updateQuestionField('${q.code}', 'practice', this.value)"
                   placeholder="Amaliyot %"
                   class="w-full px-3 py-1.5 rounded-lg border border-slate-200 bg-white text-xs focus:outline-none focus:ring-2 focus:ring-brand-500" />
          </div>
        </div>

        <div class="lg:col-span-2">
          <select onchange="updateQuestionField('${q.code}', 'video', this.value)"
                  class="w-full px-2.5 py-1.5 rounded-lg border border-slate-200 bg-white text-xs text-slate-700 focus:outline-none focus:ring-2 focus:ring-brand-500">
            <option value="" ${!data.video ? 'selected' : ''}>Video darslik?</option>
            <option value="Ha" ${data.video === 'Ha' ? 'selected' : ''}>Video: Ha</option>
            <option value="Yo'q" ${data.video === "Yo'q" ? 'selected' : ''}>Video: Yo'q</option>
          </select>
        </div>

        <div class="lg:col-span-3">
          <input type="text" value="${escapeHtml(data.comment || '')}"
                 onchange="updateQuestionField('${q.code}', 'comment', this.value)"
                 placeholder="Auditor izohi..."
                 class="w-full px-3 py-1.5 rounded-lg border border-slate-200 bg-white text-xs focus:outline-none focus:ring-2 focus:ring-brand-500" />
        </div>
      </div>
    </div>
  `;
}

function markDirty(company) {
  company.dirty = true;
  company.rev = (company.rev || 0) + 1;
}

function setQuestionAnswer(qCode, value) {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;
  markDirty(company);

  if (!company.answers[qCode]) company.answers[qCode] = {};
  company.answers[qCode].answer = value;

  // Amaliyot % javobga mos avtomatik o'zgaradi (auditor qo'lda kiritmagan bo'lsa)
  if (!company.answers[qCode].practiceManual) {
    company.answers[qCode].practice = value === 'HA' ? '100' : value === 'QISMAN' ? '50' : '0';
  }

  saveCompaniesToStorage();
  scheduleAutoSync();
  renderWorkspaceKPIs();
  renderStageTabs();
  renderQuestionsArea();
}

function updateQuestionField(qCode, field, value) {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;
  markDirty(company);

  if (!company.answers[qCode]) company.answers[qCode] = {};
  company.answers[qCode][field] = value;
  if (field === 'practice') company.answers[qCode].practiceManual = value !== '';
  saveCompaniesToStorage();
  scheduleAutoSync();
}

// 7. SYNC TO GOOGLE SHEETS & COMPLETION FLOW
let syncInFlight = false;
let syncQueued = false;
let autoSyncTimer = null;

// Javob o'zgargach 2.5 soniyadan so'ng jimgina Sheetsga yozadi
function scheduleAutoSync() {
  if (!getAppsScriptUrl()) return;
  clearTimeout(autoSyncTimer);
  autoSyncTimer = setTimeout(() => syncAuditToSheets(false, true), 2500);
}

async function syncAuditToSheets(isCompleting = false, silent = false) {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return false;

  const scriptUrl = getAppsScriptUrl();
  const syncBtn = document.getElementById('syncNowBtn');
  const origHtml = syncBtn.innerHTML;

  if (!scriptUrl) {
    if (!isCompleting && !silent) {
      showToast('Lokal xotiraga saqlandi. Google Sheets ulanmagan.', 'info');
    }
    return false;
  }

  if (syncInFlight) {          // bir vaqtda ikkita yozuv bo'lmasin
    syncQueued = true;
    return false;
  }
  syncInFlight = true;
  clearTimeout(autoSyncTimer);
  if (!silent) {
    syncBtn.disabled = true;
    syncBtn.innerHTML = '<span>Saqlanmoqda...</span>';
  }

  try {
    // Demo rejimda yaratilgan yoki nusxalanmay qolgan kompaniya uchun avval nusxa yaratamiz
    if (!company.isCloned) {
      const ok = await createSheetCopy(company);
      if (!ok) {
        if (!silent) showToast('Google Sheets nusxasini yaratib bo‘lmadi. URL va Apps Script ruxsatlarini tekshiring.', 'error');
        return false;
      }
      document.getElementById('wsSheetDirectLink').href = company.spreadsheetUrl;
    }

    const stagesPayload = EJM_TEMPLATE.map(stage => {
      const answersList = [];
      stage.blocks.forEach(block => {
        block.questions.forEach(q => {
          const a = company.answers[q.code];
          if (a) {
            answersList.push({
              tr: q.tr,
              answer: a.answer || '',
              link: a.link || '',
              responsible: a.responsible || '',
              practice: a.practice === undefined ? '' : a.practice,
              video: a.video || '',
              comment: a.comment || ''
            });
          }
        });
      });
      return { sheetName: stage.sheetName, answers: answersList };
    });

    const revAtStart = company.rev || 0;
    const resJson = await apiCall({
      action: 'sync_audit',
      spreadsheetId: company.spreadsheetId,
      status: company.status,
      stages: stagesPayload
    });
    if (resJson.status === 'success') {
      if ((company.rev || 0) === revAtStart) { company.dirty = false; saveCompaniesToStorage(); }
      if (!silent) showToast('Barcha javoblar Google Sheets jadvaliga yozildi!', 'success');
      return true;
    }
    showToast('Sheetsga yozishda xatolik: ' + (resJson.message || ''), 'error');
    return false;
  } catch (err) {
    console.error(err);
    showToast('Tarmoq xatosi: Google Sheetsga ulanib bo‘lmadi.', 'error');
    return false;
  } finally {
    syncInFlight = false;
    if (!silent) {
      syncBtn.disabled = false;
      syncBtn.innerHTML = origHtml;
    }
    if (syncQueued) {
      syncQueued = false;
      scheduleAutoSync();
    }
  }
}

async function finishDiagnosis() {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;

  company.status = 'completed';
  saveCompaniesToStorage();
  updateWorkspaceStatusBadge(company);

  const synced = await syncAuditToSheets(true);

  const stats = calculateCompanyStats(company);
  document.getElementById('compModalTitle').textContent = `${company.name} — Diagnostika Natijasi`;
  document.getElementById('compOverallPct').textContent = stats.overallScorePct + '%';
  document.getElementById('compOverallStatus').textContent = stats.levelLabel;
  document.getElementById('compMetaSummary').textContent = `To'ldirilganlik: ${stats.overallCompletionPct}% (${stats.totalAnswered}/${stats.totalQuestions})`;

  const syncBadge = document.getElementById('compSyncStatusBadge');
  if (synced && company.isCloned) {
    syncBadge.className = 'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200';
    syncBadge.innerHTML = ico('check') + 'Shaxsiy Google Sheets yangilandi';
  } else if (company.isCloned) {
    syncBadge.className = 'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold bg-rose-50 text-rose-700 border border-rose-200';
    syncBadge.innerHTML = ico('alert') + 'Sheetsga yozilmadi — “Sheetsga saqlash”ni qayta bosing';
  } else {
    syncBadge.className = 'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold bg-amber-50 text-amber-800 border border-amber-200';
    syncBadge.textContent = 'Demo rejim (Asosiy shablon havolasi)';
  }

  document.getElementById('compStagesTableBody').innerHTML = stats.stageStats.map(s => `
    <tr>
      <td class="py-2.5 px-3.5 font-semibold text-slate-800">${s.shortName}</td>
      <td class="py-2.5 px-3.5 text-center text-slate-500">${s.answered}/${s.total} (${s.completionPct}%)</td>
      <td class="py-2.5 px-3.5 text-right font-extrabold text-brand-600">${s.scorePct}%</td>
    </tr>
  `).join('');

  document.getElementById('compSheetUrlInput').value = company.spreadsheetUrl;
  document.getElementById('compOpenSheetBtn').href = company.spreadsheetUrl;

  const modal = document.getElementById('completionModal');
  modal.classList.remove('hidden');
  modal.classList.add('flex');
}

function closeCompletionModal() {
  const modal = document.getElementById('completionModal');
  modal.classList.add('hidden');
  modal.classList.remove('flex');
}

function copyTextFallback(text, successMsg) {
  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.style.position = 'fixed';
  textarea.style.opacity = '0';
  document.body.appendChild(textarea);
  textarea.select();
  try {
    document.execCommand('copy');
    showToast(successMsg, 'success');
  } catch (err) {
    showToast('Nusxalashda xatolik yuz berdi', 'error');
  }
  document.body.removeChild(textarea);
}

function copySheetLink() {
  const url = document.getElementById('compSheetUrlInput').value;
  copyTextFallback(url, 'Google Sheets havolasi nusxalandi!');
}

function copyTelegramReport() {
  const company = companies.find(c => c.id === currentCompanyId);
  if (!company) return;
  const stats = calculateCompanyStats(company);

  const stageLines = stats.stageStats
    .map(s => `• ${s.shortName}: ${s.scorePct}%`)
    .join('\n');

  const reportText = `📊 *EJM | AUDIT DIAGNOSTIKA NATIJALARI*

🏢 *Kompaniya:* ${company.name}
📅 *Sana:* ${company.auditDate}
👤 *Auditor:* ${company.auditor}

🎯 *Umumiy Tizim Darajasi:* *${stats.overallScorePct}%* (${stats.levelLabel})

📈 *Bosqichlar kesimida:*
${stageLines}

🔗 *To'liq tahlil va tavsiyalar jadvali (Google Sheets):*
${company.spreadsheetUrl}`;

  copyTextFallback(reportText, 'Biznes egasi uchun tayyor hisobot matni nusxalandi!');
}


