const STEP_BY_CODE = {};
EJM_STEPS.forEach(st => { STEP_BY_CODE[st.code] = st; });
const QUESTION_BY_CODE = {};
EJM_TEMPLATE.forEach(stg => stg.blocks.forEach(b => b.questions.forEach(q => {
  QUESTION_BY_CODE[q.code] = { q, block: b, stage: stg };
})));
const STEPS_BY_QUESTION = {};
EJM_STEPS.forEach(st => st.qs.forEach(c => { (STEPS_BY_QUESTION[c] = STEPS_BY_QUESTION[c] || []).push(st); }));

let wsPane = 'audit';
const bneckOpen = { audit: null, map: null };
let mapOnlyProblems = false;

const pcolor = p => p <= 40 ? '#F0384B' : p <= 60 ? '#F5A524' : p <= 80 ? '#2F62EE' : '#15B67A';
const LEVEL = p => (p <= 20 ? 'Kritik' : p <= 40 ? 'Zaif' : p <= 60 ? 'Rivojlanmoqda' : p <= 80 ? 'Boshqariladi' : 'Tizimlashgan');
const fmtPct = p => String(p).replace('.', ',') + '%';

function curCompany() { return companies.find(c => c.id === currentCompanyId); }

// Savollar kodlari bo'yicha ball: faqat javob berilganlar hisobga olinadi
function scoreOfCodes(company, codes) {
  const uniq = [...new Set(codes)];
  let answered = 0, points = 0;
  uniq.forEach(code => {
    const a = company.answers[code] && company.answers[code].answer;
    if (!a) return;
    answered++;
    points += a === 'HA' ? 1 : a === 'QISMAN' ? 0.5 : 0;
  });
  return { total: uniq.length, answered, points, pct: answered ? Math.round((points / answered) * 100) : 0 };
}
const stepScore = (company, st) => scoreOfCodes(company, st.qs);
const stepsOfStage = sid => EJM_STEPS.filter(st => st.stage === sid);
const stageMapScore = (company, sid) => scoreOfCodes(company, stepsOfStage(sid).flatMap(st => st.qs));
const moduleScore = (company, m) => scoreOfCodes(company, m.steps.flatMap(c => (STEP_BY_CODE[c] ? STEP_BY_CODE[c].qs : [])));

function badQuestions(company, codes) {
  return [...new Set(codes)].filter(c => {
    const a = company.answers[c] && company.answers[c].answer;
    return a && a !== 'HA';
  });
}

// ---- bo'limlar almashtirgichi ----
function setPane(pane) {
  wsPane = pane;
  ['dash', 'audit', 'bneck', 'map', 'steps'].forEach(k => {
    const pn = document.getElementById({ dash: 'wsDashPane', audit: 'wsAuditPane', bneck: 'wsBneckPane', map: 'wsMapPane', steps: 'wsStepsPane' }[k]);
    pn.classList.toggle('hidden', k !== pane);
    document.getElementById('paneBtn_' + k).className = 'shrink-0 px-4 sm:px-5 py-3.5 text-sm sm:text-[15px] font-bold border-b-4 transition ' +
      (k === pane ? 'border-brand-600 text-brand-700 bg-brand-50/60' : 'border-transparent text-slate-500 hover:text-slate-900 hover:bg-slate-50');
  });
  if (pane !== 'audit') window.scrollTo({ top: 0 });
  refreshPane();
}
function refreshPane() {
  if (!curCompany()) return;
  if (wsPane === 'dash') renderCompanyDashboard();
  else if (wsPane === 'bneck') renderBottleneck();
  else if (wsPane === 'map') renderMap();
  else if (wsPane === 'steps') renderSteps();
}

// ---- audit savoli ostidagi "qaysi qadamga tegishli" belgilar ----
function stepChipsFor(qCode) {
  const list = STEPS_BY_QUESTION[qCode];
  if (!list || !list.length) return '';
  return '<div class="flex flex-wrap gap-1.5 mt-1.5">' + list.map(st =>
    `<button type="button" onclick="openStepModal('${st.code}')" title="EJM xaritasidagi qadam"
       class="px-2 py-0.5 rounded-md bg-indigo-50 text-indigo-700 text-[11px] font-semibold hover:bg-indigo-100">${ico('map')}${st.code} ${escapeHtml(st.name)}</button>`).join('') + '</div>';
}

// ---- Bottleneck: quvur bo'lagi ----
function pipeSegment(title, icon, sc, active, onclickJs, unit) {
  const W = 132, H = 76;
  const has = sc.answered > 0;
  const pc = has ? sc.pct : 100;
  const open = Math.max(0.1, pc / 100);
  const t = (H - 8) * (1 - open) / 2;
  const color = has ? pcolor(sc.pct) : '#A7B0C0';
  const y0 = 4, y1 = H - 4;
  const d = `M0,${y0} C${W * 0.32},${y0} ${W * 0.3},${y0 + t} ${W / 2},${y0 + t} C${W * 0.7},${y0 + t} ${W * 0.68},${y0} ${W},${y0}`
    + ` L${W},${y1} C${W * 0.68},${y1} ${W * 0.7},${y1 - t} ${W / 2},${y1 - t} C${W * 0.3},${y1 - t} ${W * 0.32},${y1} 0,${y1} Z`;
  const gap = (y1 - y0) - 2 * t;
  const stuck = has && sc.pct < 60 ? Math.round((1 - sc.pct / 100) * 12) : 0;
  let dots = '';
  for (let i = 0; i < stuck; i++) {
    const col = Math.floor(i / 4), row = i % 4;
    dots += `<circle cx="${9 + col * 9 + (row % 2) * 3}" cy="${H / 2 - 15 + row * 10}" r="3.6" />`;
  }
  const tip = has ? `${title}: ${sc.pct}% — ${LEVEL(sc.pct)}` : `${title}: javob berilmagan`;
  return `
    <button type="button" class="pseg${active ? ' on' : ''}" onclick="${onclickJs}" title="${escapeHtml(tip)}">
      <div class="pseg-t"><span>${icon || ''}</span> ${escapeHtml(title)}</div>
      <svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" aria-hidden="true">
        <path d="${d}" fill="${color}" fill-opacity="${has ? 0.28 : 0.12}" stroke="${color}" stroke-width="2.5" ${has ? '' : 'stroke-dasharray="5 4"'} />
        ${has ? `<line x1="0" y1="${H / 2}" x2="${W}" y2="${H / 2}" stroke="${color}" stroke-width="${Math.max(2, gap * 0.45)}" stroke-dasharray="7 9" class="pflow" style="animation-duration:${(0.6 + (1 - open) * 2.4).toFixed(2)}s" />` : ''}
        <g fill="#7f1d1d" stroke="#fff" stroke-width="0.8" class="pstuck">${dots}</g>
      </svg>
      <div class="pseg-b">
        ${has ? `<b style="color:${color}">${fmtPct(sc.pct)}</b><small>${LEVEL(sc.pct)}${stuck > 0 ? ` · ${unit} o‘ta olmayapti` : ''}<br>${sc.answered}/${sc.total} javob</small>`
          : `<b style="color:${color}">—</b><small>javob yo‘q (${sc.total} mezon)</small>`}
      </div>
    </button>`;
}

function bneckToggle(row, id) {
  bneckOpen[row] = bneckOpen[row] === id ? null : id;
  renderBottleneck();
}

function problemLine(company, label, codes, onclickJs) {
  const bad = badQuestions(company, codes);
  if (!bad.length) return '';
  const texts = bad.slice(0, 4).map(c => escapeHtml(QUESTION_BY_CODE[c].q.text.replace(/\?$/, ''))).join(' · ');
  return `<div class="text-xs"><b ${onclickJs ? `class="cursor-pointer hover:underline" onclick="${onclickJs}"` : ''}>${escapeHtml(label)}</b> — ${bad.length} ta muammo: <span class="text-slate-600">${texts}${bad.length > 4 ? ' …' : ''}</span></div>`;
}

function bneckRow(company, key, title, unit, segs) {
  // segs: [{id,title,icon,codes,subs:[{id,title,codes,onclick?}]}]
  const scored = segs.map(sg => ({ sg, sc: scoreOfCodes(company, sg.codes) }));
  const all = scoreOfCodes(company, segs.flatMap(sg => sg.codes));
  const worst = scored.filter(x => x.sc.answered).sort((a, b) => a.sc.pct - b.sc.pct).slice(0, 3);
  const open = segs.find(sg => sg.id === bneckOpen[key]);
  let sub = '';
  if (open) {
    sub = `
      <div class="mt-2 rounded-xl border border-slate-200 bg-slate-50 p-3.5">
        <div class="flex items-center gap-2 text-sm"><b>${escapeHtml(open.title)}</b> — ichki bo‘limlar
          <button class="ml-auto text-xs font-bold text-slate-500 hover:text-slate-800" onclick="bneckToggle('${key}','${open.id}')">× yopish</button></div>
        <div class="pipe">${open.subs.map(sb => pipeSegment(sb.title, '', scoreOfCodes(company, sb.codes), false, sb.onclick || 'void 0', unit)).join('')}</div>
        <div class="space-y-1.5 mt-1">${open.subs.map(sb => problemLine(company, sb.title, sb.codes, sb.onclick)).join('')}</div>
      </div>`;
  }
  return `
    <div class="bg-white rounded-2xl border border-slate-200 shadow-sm p-5">
      <div class="flex flex-wrap items-baseline gap-3 mb-3">
        <h3 class="text-lg font-extrabold text-slate-900">${title}</h3>
        <span class="text-2xl font-extrabold" style="color:${all.answered ? pcolor(all.pct) : '#94a3b8'}">${all.answered ? fmtPct(all.pct) : '—'}</span>
        <span class="text-xs text-slate-500">${all.answered} / ${all.total} mezonga javob berilgan</span>
        ${worst.length ? `<span class="ml-auto flex flex-wrap items-center gap-1.5 text-xs text-slate-500">Eng tor joylar: ${worst.map((x, i) =>
          `<button class="px-2.5 py-0.5 rounded-full bg-slate-100 font-bold hover:bg-slate-200" style="color:${pcolor(x.sc.pct)}" onclick="bneckToggle('${key}','${x.sg.id}')">${i + 1}. ${escapeHtml(x.sg.title)} (${fmtPct(x.sc.pct)})</button>`).join('')}</span>` : ''}
      </div>
      ${all.answered ? '' : '<div class="text-xs text-slate-500 mb-2">Bu bo‘lim bo‘yicha hali javob kiritilmagan — «Audit savollari» bo‘limida to‘ldiring.</div>'}
      <div class="pipe">
        <div class="pipe-in">${unit === 'xodim' ? 'Nomzodlar / xodimlar' : 'Oqim'} →</div>
        ${scored.map(({ sg, sc }) => pipeSegment(sg.title, sg.icon, sc, sg.id === bneckOpen[key], `bneckToggle('${key}','${sg.id}')`, unit)).join('')}
        <div class="pipe-out">→ Natija</div>
      </div>
      ${sub}
    </div>`;
}

function renderBottleneck() {
  const company = curCompany();
  const pane = document.getElementById('wsBneckPane');
  if (!company) return;

  // 1-qator: audit bosqichlari -> bloklar
  const auditSegs = EJM_TEMPLATE.map(stg => ({
    id: stg.id, title: stg.shortName, icon: '',
    codes: stg.blocks.flatMap(b => b.questions.map(q => q.code)),
    subs: stg.blocks.map(b => ({ title: b.title, codes: b.questions.map(q => q.code) }))
  }));
  // 2-qator: EJM xaritasi bosqichlari -> qadamlar
  const mapSegs = MAP_STAGES.map(ms => ({
    id: ms.id, title: ms.short, icon: '',
    codes: stepsOfStage(ms.id).flatMap(st => st.qs),
    subs: stepsOfStage(ms.id).map(st => ({ title: st.code + ' ' + st.name, codes: st.qs, onclick: `openStepModal('${st.code}')` }))
  }));

  const legend = [[90, 'Tizimlashgan'], [70, 'Boshqariladi'], [50, 'Rivojlanmoqda'], [30, 'Zaif / kritik']]
    .map(([pc, n]) => `<span class="inline-flex items-center gap-1.5"><i class="inline-block w-3 h-3 rounded" style="background:${pcolor(pc)}"></i>${n}</span>`).join('');

  pane.innerHTML = `
    <div class="flex flex-wrap items-end gap-3">
      <div class="flex-1 min-w-[260px]">
        <h2 class="text-2xl font-extrabold text-slate-900">${ico('funnel')}Bottleneck — tor joylar</h2>
        <p class="text-sm text-slate-500">Har bir bo‘lim — quvur bo‘lagi. Ball qancha past bo‘lsa, quvur shuncha tor: oqim sekinlashadi va oldida odamlar to‘planib qoladi. Bo‘lim ustiga bossangiz, ichki bo‘limlari ochiladi.</p>
      </div>
      <div class="flex flex-wrap items-center gap-3 text-xs text-slate-600">${legend}</div>
    </div>
    ${bneckRow(company, 'audit', 'Audit bosqichlari (6 bosqich · 36 blok)', 'xodim', auditSegs)}
    ${bneckRow(company, 'map', 'EJM xaritasi (Xodim fabrikasi · 67 qadam)', 'xodim', mapSegs)}
    <p class="text-xs text-slate-400">Ball faqat javob berilgan mezonlar bo‘yicha hisoblanadi (HA=1, QISMAN=0,5, YO'Q=0). Qadam ustiga bossangiz, unga bog‘langan audit savollari ochiladi.</p>`;
}

// ---- EJM xaritasi (Xodim fabrikasi) ----
function scorePill(sc, small) {
  if (!sc.answered) return `<span class="shrink-0 ${small ? 'text-[10px] px-1.5' : 'text-[11px] px-2'} py-0.5 rounded-full bg-slate-100 text-slate-400 font-bold">—</span>`;
  const c = pcolor(sc.pct);
  return `<span class="shrink-0 ${small ? 'text-[10px] px-1.5' : 'text-[11px] px-2'} py-0.5 rounded-full font-extrabold text-white" style="background:${c}">${sc.pct}%</span>`;
}

function toggleMapProblems() { mapOnlyProblems = !mapOnlyProblems; renderMap(); }

function renderMap() {
  const company = curCompany();
  const pane = document.getElementById('wsMapPane');
  if (!company) return;

  const linkedSteps = EJM_STEPS.filter(st => st.qs.length);
  const evaluated = linkedSteps.filter(st => stepScore(company, st).answered > 0).length;
  const total = scoreOfCodes(company, EJM_STEPS.flatMap(st => st.qs));

  const cols = MAP_STAGES.map(ms => {
    const sc = stageMapScore(company, ms.id);
    const steps = stepsOfStage(ms.id).filter(st => !mapOnlyProblems || badQuestions(company, st.qs).length > 0);
    const mods = EJM_MODULES.filter(m => m.stage === ms.id && !m.code.startsWith('A-'));
    const att = EJM_MODULES.find(m => m.stage === ms.id && m.code.startsWith('A-'));
    const range = stepsOfStage(ms.id);
    const stepsHtml = steps.map(st => {
      const ss = stepScore(company, st);
      return `<button type="button" class="mstep" onclick="openStepModal('${st.code}')" title="${escapeHtml(st.name)}">
          <b class="shrink-0 text-slate-900">${st.code}</b><span class="flex-1 text-slate-700 leading-tight">${escapeHtml(st.name)}</span>${scorePill(ss, true)}</button>`;
    }).join('') || '<div class="text-xs text-slate-400 p-2">Muammoli qadam yo‘q</div>';

    const modsHtml = mods.map(m => {
      const ms2 = moduleScore(company, m);
      const general = m.type === 'Umumiy';
      return `<button type="button" onclick="openModuleModal('${m.code}')" class="block w-full text-left bg-white rounded-xl border border-slate-200 border-l-4 p-3 hover:shadow-md transition" style="border-left-color:${ms.color}">
          <div class="flex items-start justify-between gap-2"><span class="text-[11px] font-bold text-slate-400">${m.code}</span>${scorePill(ms2, true)}</div>
          <div class="text-sm font-extrabold text-slate-900 leading-snug">${escapeHtml(m.name)}</div>
          <span class="inline-block mt-1 px-1.5 py-0.5 rounded text-[10px] font-bold ${general ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}">${escapeHtml(m.type)}</span>
          <div class="text-[11px] text-slate-500 mt-1 leading-snug">Attestatsiya: ${escapeHtml(m.attest || '')}</div>
        </button>`;
    }).join('');

    const attHtml = att ? (() => {
      const as = moduleScore(company, att);
      return `<button type="button" onclick="openModuleModal('${att.code}')" class="block w-full text-left rounded-xl p-3 text-white hover:opacity-95" style="background:${ms.color}">
          <div class="flex items-start justify-between gap-2"><span class="text-sm font-extrabold">${ico('lock')}Bosqich attestatsiyasi</span>${as.answered ? `<span class="text-[11px] px-2 py-0.5 rounded-full bg-white/90 font-extrabold" style="color:${pcolor(as.pct)}">${as.pct}%</span>` : ''}</div>
          <div class="text-[11px] opacity-90 mt-1 leading-snug">${escapeHtml(att.pass || '')}</div></button>`;
    })() : '';

    const note = ms.id === 'T' ? 'Lavozimga xos modullar shu paketdan quriladi. Umumiy modullar kompaniyada 1 marta quriladi.'
      : ms.id === '1' ? 'Qabul qilingan offer → Pre-boarding boshlanadi.' : '';

    return `
      <div class="mapcol space-y-3">
        <div class="chev text-white font-extrabold text-sm px-4 py-3 flex items-center justify-between gap-2" style="background:${ms.color}">
          <span>${escapeHtml(ms.name)}</span>
          ${sc.answered ? `<span class="text-[11px] px-2 py-0.5 rounded-full bg-white/90 font-extrabold mr-3" style="color:${pcolor(sc.pct)}">${sc.pct}%</span>` : ''}
        </div>
        <div class="text-[11px] text-slate-500 min-h-[30px]">${escapeHtml(ms.when)}</div>
        <div class="bg-white rounded-xl border border-slate-200 p-2">
          <div class="text-[11px] font-bold text-slate-500 px-1.5 pb-1">${ms.id === 'T' ? 'Lavozim paketi' : 'Qadamlar'} (${range[0].code}–${range[range.length - 1].code})</div>
          ${stepsHtml}
        </div>
        ${note ? `<div class="rounded-xl bg-slate-50 border border-slate-200 p-2.5 text-[11px] text-slate-600"><b class="text-slate-500">NATIJA</b><br>${escapeHtml(note)}</div>` : ''}
        ${modsHtml}
        ${attHtml}
      </div>`;
  }).join('');

  const s6 = scoreOfCodes(company, EJM_TEMPLATE[5].blocks.flatMap(b => b.questions.map(q => q.code)));
  pane.innerHTML = `
    <div class="flex flex-wrap items-end gap-3">
      <div class="flex-1 min-w-[260px]">
        <h2 class="text-2xl font-extrabold text-slate-900">${ico('map')}EJM xaritasi · Xodim fabrikasi</h2>
        <p class="text-sm text-slate-500">Barcha lavozimlar uchun yagona tizim: lavozim paketi → 5 bosqich. Har modul = video darslik + checklist + attestatsiya. Qadam yoki modul ustiga bosing — unga bog‘langan audit savollari ochiladi va shu yerning o‘zida javob berish mumkin.</p>
      </div>
      <div class="flex items-center gap-3 text-xs">
        <span class="px-3 py-1.5 rounded-xl bg-slate-100 text-slate-700">Baholangan qadamlar: <b>${evaluated}</b> / ${linkedSteps.length}</span>
        <span class="px-3 py-1.5 rounded-xl bg-slate-100 text-slate-700">Xarita natijasi: <b style="color:${total.answered ? pcolor(total.pct) : '#94a3b8'}">${total.answered ? total.pct + '%' : '—'}</b></span>
        <button onclick="toggleMapProblems()" class="px-3 py-1.5 rounded-xl font-semibold ${mapOnlyProblems ? 'bg-rose-600 text-white' : 'bg-white border border-slate-200 text-slate-700 hover:bg-slate-50'}">Faqat muammoli qadamlar</button>
      </div>
    </div>
    <div class="overflow-x-auto pb-3">
      <div class="grid gap-3" style="grid-template-columns:repeat(6,minmax(180px,1fr));min-width:1140px">${cols}</div>
    </div>
    <div class="grid grid-cols-1 md:grid-cols-3 gap-3">
      <div class="rounded-xl bg-slate-50 border border-slate-200 p-3 text-xs text-slate-600"><b>6. EJM boshqaruvi</b> (audit natijasi: <b style="color:${s6.answered ? pcolor(s6.pct) : '#94a3b8'}">${s6.answered ? s6.pct + '%' : '—'}</b>): lavozim paketlari versiyasi va yillik yangilanishi · pilot · samaradorlik ko‘rsatkichlari</div>
      <div class="rounded-xl bg-slate-50 border border-slate-200 p-3 text-xs text-slate-600"><b>O‘lchanadi:</b> mustaqil ishga o‘tish muddati · sinovda ketganlar % · attestatsiyadan 1-urinishda o‘tish % · 90 kunlik saqlanish · eNPS</div>
      <div class="rounded-xl bg-slate-50 border border-slate-200 p-3 text-xs text-slate-600"><span class="px-1.5 py-0.5 rounded bg-emerald-50 text-emerald-700 font-bold text-[10px]">Umumiy</span> kompaniyada 1 marta &nbsp; <span class="px-1.5 py-0.5 rounded bg-blue-50 text-blue-700 font-bold text-[10px]">Lavozimga xos</span> har lavozimga alohida</div>
    </div>`;
}

// ---- qadam / modul oynasi ----
let openStepCode = null, openModuleCode = null;

function modalAnswerButtons(code, ans) {
  const cls = (v, on, off) => `answer-btn px-2.5 py-1 rounded-lg border text-[11px] font-extrabold ${ans === v ? on : off}`;
  const q = JSON.stringify(code);
  return `<div class="flex items-center gap-1.5 shrink-0">
    <button type="button" onclick='modalAnswer(${q},"HA")' class="${cls('HA', 'bg-emerald-600 text-white border-emerald-600', 'bg-white text-slate-700 border-slate-200 hover:bg-emerald-50')}">HA</button>
    <button type="button" onclick='modalAnswer(${q},"QISMAN")' class="${cls('QISMAN', 'bg-amber-500 text-white border-amber-500', 'bg-white text-slate-700 border-slate-200 hover:bg-amber-50')}">QISMAN</button>
    <button type="button" onclick='modalAnswer(${q},"YO\\u2019Q")' class="${cls("YO'Q", 'bg-rose-600 text-white border-rose-600', 'bg-white text-slate-700 border-slate-200 hover:bg-rose-50')}">YO'Q</button>
  </div>`;
}

function modalQuestionList(company, codes) {
  if (!codes.length) return '<div class="text-xs text-slate-500 p-3 rounded-xl bg-slate-50">Bu qadam uchun auditda alohida savol yo‘q («Yangi» qadam).</div>';
  return '<div class="divide-y divide-slate-100 border border-slate-200 rounded-xl overflow-hidden">' + codes.map(c => {
    const qi = QUESTION_BY_CODE[c];
    const ans = (company.answers[c] && company.answers[c].answer) || '';
    return `<div class="p-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
      <div class="flex items-start gap-2 text-sm">
        <span class="px-1.5 py-0.5 rounded bg-slate-100 text-slate-600 font-mono text-[11px] font-bold shrink-0 mt-0.5">${c}</span>
        <div><span class="text-slate-800 font-medium leading-snug">${escapeHtml(qi.q.text)}</span>
        <button type="button" class="block text-[11px] text-brand-600 hover:underline" onclick="goToQuestion('${c}')">Audit savollarida ochish →</button></div>
      </div>
      ${modalAnswerButtons(c, ans)}
    </div>`;
  }).join('') + '</div>';
}

function showStepModal() {
  const modal = document.getElementById('stepModal');
  modal.classList.remove('hidden'); modal.classList.add('flex');
}
function closeStepModal() {
  const modal = document.getElementById('stepModal');
  modal.classList.add('hidden'); modal.classList.remove('flex');
  openStepCode = null; openModuleCode = null;
}

function infoRow(label, val) {
  if (!val) return '';
  return `<div class="grid grid-cols-3 gap-3 text-sm py-1.5 border-b border-slate-100"><div class="text-xs font-bold text-slate-500 uppercase tracking-wide">${label}</div><div class="col-span-2 text-slate-800">${escapeHtml(val)}</div></div>`;
}

function renderStepModal() {
  const company = curCompany();
  const st = STEP_BY_CODE[openStepCode];
  if (!company || !st) return;
  const ms = MAP_STAGES.find(x => x.id === st.stage);
  const sc = stepScore(company, st);
  const mods = EJM_MODULES.filter(m => m.steps.includes(st.code));
  document.getElementById('stepModalBody').innerHTML = `
    <div class="px-6 py-4 text-white flex items-start justify-between gap-3" style="background:${ms.color}">
      <div><div class="text-xs font-semibold opacity-90">${escapeHtml(ms.name)} · ${escapeHtml(st.phase || '')}</div>
        <h3 class="text-xl font-extrabold">${st.code} · ${escapeHtml(st.name)}</h3></div>
      <div class="flex items-center gap-2">
        ${sc.answered ? `<span class="px-2.5 py-1 rounded-full bg-white font-extrabold text-sm" style="color:${pcolor(sc.pct)}">${sc.pct}%</span>` : ''}
        <button onclick="closeStepModal()" class="p-1 rounded-lg hover:bg-white/15" aria-label="Yopish">${icon('x', 18)}</button>
      </div>
    </div>
    <div class="p-6 space-y-4 max-h-[75vh] overflow-y-auto">
      <div>${infoRow('Nima qilinadi', st.what)}${infoRow('Mas’ul', st.who)}${infoRow('Qachon', st.when)}${infoRow('Instrument', st.tool)}${infoRow('Kutilgan natija', st.result)}${infoRow('Baholash mezoni', st.criterion)}
        ${mods.length ? infoRow('Modul', mods.map(m => m.code + ' ' + m.name).join('; ')) : ''}</div>
      <div>
        <h4 class="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Diagnostika savollari (${st.qs.length}) — ${sc.answered}/${sc.total} javob berilgan</h4>
        ${modalQuestionList(company, st.qs)}
      </div>
    </div>`;
}

function openStepModal(code) {
  openStepCode = code; openModuleCode = null;
  renderStepModal(); showStepModal();
}

function openModuleModal(code) {
  openModuleCode = code; openStepCode = null;
  renderModuleModal(); showStepModal();
}

function renderModuleModal() {
  const company = curCompany();
  const m = EJM_MODULES.find(x => x.code === openModuleCode);
  if (!company || !m) return;
  const ms = MAP_STAGES.find(x => x.id === m.stage);
  const codes = m.steps.flatMap(c => (STEP_BY_CODE[c] ? STEP_BY_CODE[c].qs : []));
  const sc = moduleScore(company, m);
  document.getElementById('stepModalBody').innerHTML = `
    <div class="px-6 py-4 text-white flex items-start justify-between gap-3" style="background:${ms.color}">
      <div><div class="text-xs font-semibold opacity-90">${escapeHtml(ms.name)} · ${escapeHtml(m.type || '')}</div>
        <h3 class="text-xl font-extrabold">${m.code} · ${escapeHtml(m.name)}</h3></div>
      <div class="flex items-center gap-2">
        ${sc.answered ? `<span class="px-2.5 py-1 rounded-full bg-white font-extrabold text-sm" style="color:${pcolor(sc.pct)}">${sc.pct}%</span>` : ''}
        <button onclick="closeStepModal()" class="p-1 rounded-lg hover:bg-white/15" aria-label="Yopish">${icon('x', 18)}</button>
      </div>
    </div>
    <div class="p-6 space-y-4 max-h-[75vh] overflow-y-auto">
      <div>${infoRow('Maqsad', m.goal)}${infoRow('Video darslik mavzulari', m.videos)}${infoRow('Checklist bandlari', m.checklist)}${infoRow('Checklist mas’uli', m.owner)}
        ${infoRow('Attestatsiya turi', m.attest)}${infoRow('O‘tish mezoni', m.pass)}${infoRow('Davomiyligi', m.duration)}</div>
      <div>
        <h4 class="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Bog‘langan qadamlar</h4>
        <div class="flex flex-wrap gap-1.5">${m.steps.filter(c => STEP_BY_CODE[c]).map(c => `<button class="px-2 py-1 rounded-lg bg-slate-100 text-xs font-semibold hover:bg-slate-200" onclick="openStepModal('${c}')">${c} ${escapeHtml(STEP_BY_CODE[c].name)}</button>`).join('')}</div>
      </div>
      <div>
        <h4 class="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">Diagnostika savollari (${[...new Set(codes)].length}) — ${sc.answered}/${sc.total} javob berilgan</h4>
        ${modalQuestionList(company, [...new Set(codes)])}
      </div>
    </div>`;
}

// Oyna ichida javob berish: audit bilan bir xil mantiq (ball, avto-saqlash, Sheets)
function modalAnswer(code, value) {
  setQuestionAnswer(code, value === 'YO\u2019Q' ? "YO'Q" : value);
  if (openStepCode) renderStepModal(); else if (openModuleCode) renderModuleModal();
  refreshPane();
}

function goToQuestion(code) {
  closeStepModal();
  const info = QUESTION_BY_CODE[code];
  setPane('audit');
  questionFilter = 'ALL';
  document.getElementById('questionSearchInput').value = '';
  selectStage(info.stage.id);
  setTimeout(() => {
    const el = document.getElementById('q-' + code);
    if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); el.classList.add('ring-2', 'ring-brand-500'); setTimeout(() => el.classList.remove('ring-2', 'ring-brand-500'), 2200); }
  }, 60);
}

// ==================== KOMPANIYA DASHBOARDI ====================
function scoreColor(pct) {
  if (pct >= 80) return { bar: 'bg-emerald-500', text: 'text-emerald-600' };
  if (pct >= 50) return { bar: 'bg-brand-600', text: 'text-brand-600' };
  if (pct >= 25) return { bar: 'bg-amber-500', text: 'text-amber-600' };
  return { bar: 'bg-rose-500', text: 'text-rose-600' };
}

function statBar(pct, label, extra, onclick) {
  const c = scoreColor(pct);
  return `
    <div class="${onclick ? 'cursor-pointer hover:bg-slate-50 rounded-lg -mx-2 px-2 py-1' : 'py-1'}" ${onclick ? `onclick="${onclick}"` : ''}>
      <div class="flex items-center justify-between gap-3 text-xs sm:text-sm">
        <span class="font-semibold text-slate-800 truncate">${label}</span>
        <span class="shrink-0"><b class="${c.text}">${pct}%</b>${extra ? `<span class="text-slate-400 ml-2">${extra}</span>` : ''}</span>
      </div>
      <div class="w-full h-2 bg-slate-100 rounded-full mt-1 overflow-hidden">
        <div class="h-full ${c.bar} rounded-full" style="width:${pct}%"></div>
      </div>
    </div>`;
}

function openAuditStage(stageId, filter) {
  setPane('audit');
  questionFilter = filter || 'ALL';
  selectStage(stageId);
  if (typeof setQuestionFilter === 'function') setQuestionFilter(questionFilter);
}

function renderCompanyDashboard() {
  const company = curCompany();
  const pane = document.getElementById('wsDashPane');
  if (!company) return;

  const st = calculateCompanyStats(company);
  const unanswered = st.totalQuestions - st.totalAnswered;
  const pctOf = n => st.totalAnswered ? Math.round((n / st.totalAnswered) * 100) : 0;
  const mapTotal = scoreOfCodes(company, EJM_STEPS.flatMap(x => x.qs));
  const linked = EJM_STEPS.filter(x => x.qs.length);
  const evaluated = linked.filter(x => stepScore(company, x).answered > 0).length;

  // Bosqichlar (audit)
  const stageRows = st.stageStats.map(s => statBar(s.scorePct, escapeHtml(s.shortName), `${s.answered}/${s.total} javob`,
    `openAuditStage('${s.id}')`)).join('');

  // Eng muammoli bloklar
  const blocks = [];
  EJM_TEMPLATE.forEach(stg => stg.blocks.forEach(b => {
    const sc = scoreOfCodes(company, b.questions.map(q => q.code));
    if (sc.answered) blocks.push({ stg, b, sc });
  }));
  blocks.sort((a, c) => a.sc.pct - c.sc.pct);
  const weakBlocks = blocks.slice(0, 8).map(x => statBar(x.sc.pct, escapeHtml(x.b.title), `${x.sc.answered}/${x.sc.total}`,
    `openAuditStage('${x.stg.id}', 'GAPS')`)).join('') || '<p class="text-xs text-slate-400">Javoblar hali kiritilmagan</p>';

  // EJM xaritasi bosqichlari
  const mapRows = MAP_STAGES.map(ms => {
    const sc = stageMapScore(company, ms.id);
    return statBar(sc.answered ? sc.pct : 0, escapeHtml(ms.name), sc.answered ? `${sc.answered}/${sc.total} javob` : 'javob yo‘q', `setPane('map')`);
  }).join('');

  // Eng muammoli qadamlar
  const steps = linked.map(x => ({ x, sc: stepScore(company, x) })).filter(y => y.sc.answered).sort((a, c) => a.sc.pct - c.sc.pct);
  const weakSteps = steps.slice(0, 8).map(y => statBar(y.sc.pct, escapeHtml(y.x.code + ' ' + y.x.name), `${y.sc.answered}/${y.sc.total}`,
    `openStepModal('${y.x.code}')`)).join('') || '<p class="text-xs text-slate-400">Javoblar hali kiritilmagan</p>';

  const kpi = (title, value, sub, color) => `
    <div class="p-4 rounded-2xl bg-white border border-slate-200 shadow-sm">
      <div class="text-xs font-medium text-slate-500">${title}</div>
      <div class="text-2xl sm:text-3xl font-extrabold mt-1" style="color:${color || '#0f172a'}">${value}</div>
      <div class="text-[11px] text-slate-400 mt-1">${sub}</div>
    </div>`;
  const card = (title, body, hint) => `
    <div class="p-5 rounded-2xl bg-white border border-slate-200 shadow-sm space-y-2">
      <div class="flex items-baseline justify-between gap-2 mb-1"><h3 class="text-sm font-bold text-slate-900">${title}</h3>${hint ? `<span class="text-[11px] text-slate-400">${hint}</span>` : ''}</div>${body}</div>`;

  pane.innerHTML = `
    <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
      ${kpi('Umumiy EJM darajasi', st.overallScorePct + '%', st.levelLabel, pcolor(st.overallScorePct))}
      ${kpi('To‘ldirilganlik', st.overallCompletionPct + '%', `${st.totalAnswered} / ${st.totalQuestions} savol`)}
      ${kpi('EJM xaritasi natijasi', mapTotal.answered ? mapTotal.pct + '%' : '—', `${evaluated} / ${linked.length} qadam baholangan`, mapTotal.answered ? pcolor(mapTotal.pct) : '#94a3b8')}
      ${kpi('Javoblar', st.totalAnswered, `HA ${st.countHa} • QISMAN ${st.countQisman} • YO'Q ${st.countYoq}`)}
    </div>

    ${radarCard(company)}

    ${unanswered > 0 ? `<div class="flex flex-wrap items-center justify-between gap-3 p-4 rounded-2xl bg-amber-50 border border-amber-200 text-sm text-amber-900">
      <span><b>${unanswered} ta savol</b> hali javobsiz — natija to‘liq bo‘lishi uchun auditni davom ettiring.</span>
      <button class="px-4 py-2 rounded-xl bg-amber-600 hover:bg-amber-700 text-white text-xs font-bold" onclick="openAuditStage('stage_1','UNANSWERED')">Auditni davom ettirish →</button></div>` : ''}

    <div class="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-5">
      ${card('Audit bosqichlari bo‘yicha natija', stageRows, 'bosqichni bosing')}
      ${card('EJM xaritasi bosqichlari', mapRows, 'xaritani ochish')}
    </div>

    <div class="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-5">
      ${card('Eng muammoli bloklar', weakBlocks, 'eng past natija')}
      ${card('Eng muammoli qadamlar (EJM xaritasi)', weakSteps, 'qadamni bosing')}
    </div>

    ${card('Javoblar taqsimoti', `
      <div class="flex w-full h-4 rounded-full overflow-hidden bg-slate-100">
        <div class="bg-emerald-500" style="width:${pctOf(st.countHa)}%"></div>
        <div class="bg-amber-400" style="width:${pctOf(st.countQisman)}%"></div>
        <div class="bg-rose-500" style="width:${pctOf(st.countYoq)}%"></div>
      </div>
      <div class="flex flex-wrap gap-x-5 gap-y-1 text-xs text-slate-600 pt-1">
        <span><b class="text-emerald-600">HA</b> ${pctOf(st.countHa)}% (${st.countHa})</span>
        <span><b class="text-amber-600">QISMAN</b> ${pctOf(st.countQisman)}% (${st.countQisman})</span>
        <span><b class="text-rose-600">YO'Q</b> ${pctOf(st.countYoq)}% (${st.countYoq})</span>
        <span class="text-slate-400">Javobsiz: ${unanswered}</span>
      </div>`)}`;
}

// ==================== EJM QADAMLARI (serpantin kartalar, tepadan pastga) ====================
const PHASE_COLORS = {
  T: ['#E8A33D', '#12284C', '#D9453A', '#5B4AA3'],
  '1': ['#2D6A4F', '#C8532B', '#2A7FBA', '#7A5C2E'],
  '2': ['#E8A33D', '#12284C', '#D9453A'],
  '3': ['#5B4AA3', '#2D6A4F', '#C8532B', '#2A7FBA'],
  '4': ['#E8A33D', '#12284C', '#D9453A', '#5B4AA3', '#2D6A4F'],
  '5': ['#E8A33D', '#12284C', '#D9453A', '#5B4AA3', '#2D6A4F']
};
let stepsOnlyProblems = false;

// Qadam nomiga qarab belgi (kalit so'z bo'yicha)
const STEP_ICON_RULES = [
  [/profil|portret/i, 'briefcase'], [/xronometraj|ishlar ro.yxati/i, 'timer'], [/sop|standart/i, 'book'], [/video/i, 'video'],
  [/kirish testi|test va topshiriq|assessment|imtihon/i, 'filecheck'], [/kpi/i, 'chart'], [/karyera|darajani/i, 'chevrons'],
  [/checklist/i, 'checksquare'], [/skript/i, 'message'], [/vakansiya/i, 'megaphone'], [/rezyume|filtr/i, 'search'], [/bazasi/i, 'database'],
  [/telefon/i, 'phone'], [/intervyu(?!.*exit)/i, 'mic'], [/amaliy sinov/i, 'flask'], [/offer|maosh/i, 'banknote'], [/rad etil/i, 'mail'],
  [/hujjat|shartnoma/i, 'file'], [/mentor/i, 'cap'], [/xush kelibsiz|jamoaga e.lon/i, 'smile'],
  [/pre-learning|o.qitish|trening|modul|chorak/i, 'layers'], [/ish joyi|access|jihoz/i, 'laptop'], [/birinchi kun/i, 'door'],
  [/lavozimga kiritish/i, 'target'], [/qoidalar/i, 'filetext'], [/platforma|instrument/i, 'wrench'], [/feedback|1:1|suhbat/i, 'message'],
  [/\d+-kun|tekshiruv/i, 'search'], [/rivojlanish|idp|maqsad|amalda/i, 'sprout'], [/tirof|mukofot/i, 'trophy'],
  [/ketish xavfi/i, 'alert'], [/zaxira|o.rinbosar/i, 'users'], [/tajriba|knowledge/i, 'brain'], [/ariza|xabardor/i, 'pen'],
  [/exit/i, 'logout'], [/handover|topshir/i, 'repeat'], [/hisob-kitob/i, 'receipt'], [/yopish/i, 'lock'], [/tahlil/i, 'trending'],
  [/alumni|aloqa|qayta chorlash/i, 'heart'], [/tadbir/i, 'sparkles'], [/lavozimga ko.tarilish/i, 'rocket'], [/jamoa/i, 'users']
];
const STAGE_ICON = { T: 'audit', '1': 'userplus', '2': 'rocket', '3': 'compass', '4': 'trending', '5': 'logout' };
function stepIcon(st) {
  for (const [re, ic] of STEP_ICON_RULES) if (re.test(st.name)) return ic;
  return STAGE_ICON[st.stage] || 'dot';
}

function toggleStepsProblems() { stepsOnlyProblems = !stepsOnlyProblems; renderSteps(); }
function jumpToStage(id) {
  const el = document.getElementById('stg-' + id);
  if (el) window.scrollTo({ top: el.getBoundingClientRect().top + window.scrollY - 175, behavior: 'smooth' });
}
function stepsColumns() {
  const w = document.getElementById('wsStepsPane').clientWidth || window.innerWidth;
  return w >= 1000 ? 5 : w >= 760 ? 4 : w >= 520 ? 3 : 2;
}

function renderSteps() {
  const company = curCompany();
  const pane = document.getElementById('wsStepsPane');
  if (!company) return;
  const cols = stepsColumns();

  const linked = EJM_STEPS.filter(x => x.qs.length);
  const evaluated = linked.filter(x => stepScore(company, x).answered > 0).length;
  const total = scoreOfCodes(company, EJM_STEPS.flatMap(x => x.qs));

  const jump = MAP_STAGES.map(ms => {
    const sc = stageMapScore(company, ms.id);
    return `<button type="button" onclick="jumpToStage('${ms.id}')" class="px-3 py-1.5 rounded-lg text-xs font-bold text-white hover:opacity-90" style="background:${ms.color}">${escapeHtml(ms.short)}${sc.answered ? ` · ${sc.pct}%` : ''}</button>`;
  }).join('');

  const sections = MAP_STAGES.map(ms => {
    const all = stepsOfStage(ms.id);
    const palette = PHASE_COLORS[ms.id];
    const phaseOrder = [];
    all.forEach(x => { if (!phaseOrder.includes(x.phase)) phaseOrder.push(x.phase); });
    const sc = stageMapScore(company, ms.id);
    const att = EJM_MODULES.find(m => m.stage === ms.id && m.code.startsWith('A-'));
    const list = all.filter(x => !stepsOnlyProblems || badQuestions(company, x.qs).length > 0);

    const cardOf = (x, idx, rowLen, rtl) => {
      const gnum = EJM_STEPS.indexOf(x) + 1;
      const col = palette[phaseOrder.indexOf(x.phase) % palette.length];
      const ss = stepScore(company, x);
      const hasNext = idx < rowLen - 1;
      return `
        <div class="relative" style="direction:ltr">
          <button type="button" onclick="openStepModal('${x.code}')" title="${escapeHtml(x.name)}"
            class="relative w-full h-full pt-7 pb-3 px-2 rounded-2xl border text-center hover:shadow-lg hover:-translate-y-0.5 transition"
            style="border-color:${col}55;background:linear-gradient(#fff 55%,${col}14)">
            <span class="absolute -top-4 left-1/2 -translate-x-1/2 w-9 h-9 rounded-full text-white font-extrabold text-sm flex items-center justify-center shadow ring-2 ring-white" style="background:${col}">${gnum}</span>
            <div class="leading-none flex justify-center" style="color:${col}">${icon(stepIcon(x), 30)}</div>
            <div class="font-extrabold text-[13px] leading-tight text-slate-900 mt-2 min-h-[34px] flex items-center justify-center">${escapeHtml(x.name)}</div>
            <div class="text-[10px] text-slate-400 mt-0.5">${x.code} · ${escapeHtml(x.phase || '')}</div>
            <div class="mt-1.5">${scorePill(ss, true)}</div>
          </button>
          ${hasNext ? `<span class="absolute top-1/2 -translate-y-1/2 pointer-events-none flex" style="color:${col};${rtl ? 'left:-22px' : 'right:-22px'}">${icon(rtl ? 'chevleft' : 'chevright', 20)}</span>` : ''}
        </div>`;
    };

    let body = '';
    for (let r = 0; r * cols < list.length; r++) {
      const row = list.slice(r * cols, (r + 1) * cols);
      const rtl = r % 2 === 1;
      const last = (r + 1) * cols >= list.length;
      body += `<div class="grid gap-x-11" style="grid-template-columns:repeat(${cols},minmax(0,1fr));direction:${rtl ? 'rtl' : 'ltr'};margin-top:22px">
        ${row.map((x, i) => cardOf(x, i, row.length, rtl)).join('')}</div>`;
      if (!last) {
        body += `<div class="grid gap-x-11" style="grid-template-columns:repeat(${cols},minmax(0,1fr));direction:${rtl ? 'rtl' : 'ltr'}">
          <div style="grid-column:${cols};direction:ltr" class="flex justify-center"><div class="h-5 border-l-2 border-dashed" style="border-color:${ms.color}88"></div></div></div>`;
      }
    }
    if (!list.length) body = '<div class="text-sm text-slate-400 py-4">Muammoli qadam yo‘q</div>';

    const attBlock = att ? `<button type="button" onclick="openModuleModal('${att.code}')" class="block w-full text-left rounded-xl p-3.5 text-white mt-6 hover:opacity-95" style="background:${ms.color}">
        <div class="text-sm font-extrabold">${ico('lock')}Bosqich attestatsiyasi — ${escapeHtml(ms.short)}</div>
        <div class="text-xs opacity-90 mt-0.5">${escapeHtml(att.pass || '')}</div></button>` : '';

    return `
      <section id="stg-${ms.id}" class="scroll-mt-40">
        <div class="sticky z-10 chev text-white font-extrabold px-5 py-3 flex items-center justify-between gap-3" style="background:${ms.color};top:116px">
          <span class="text-base sm:text-lg">${escapeHtml(ms.name)}</span>
          <span class="flex items-center gap-2 pr-3">
            <span class="hidden sm:inline text-[11px] font-semibold opacity-90">${escapeHtml(ms.when)}</span>
            ${sc.answered ? `<span class="text-[11px] px-2 py-0.5 rounded-full bg-white font-extrabold" style="color:${pcolor(sc.pct)}">${sc.pct}%</span>` : ''}
          </span>
        </div>
        ${body}
        ${attBlock}
      </section>`;
  }).join('<div class="h-10"></div>');

  pane.innerHTML = `
    <div class="flex flex-wrap items-end gap-3">
      <div class="flex-1 min-w-[260px]">
        <h2 class="text-2xl font-extrabold text-slate-900">${ico('compass')}EJM qadamlari · 67 qadam</h2>
        <p class="text-sm text-slate-500">Lavozim paketidan alumnigacha — barcha qadamlar tartib raqami bilan, tepadan pastga. Qadam ustiga bossangiz, tafsiloti va unga bog‘langan diagnostika savollari ochiladi.</p>
      </div>
      <div class="flex items-center gap-3 text-xs">
        <span class="px-3 py-1.5 rounded-xl bg-slate-100 text-slate-700">Baholangan: <b>${evaluated}</b> / ${linked.length}</span>
        <span class="px-3 py-1.5 rounded-xl bg-slate-100 text-slate-700">Natija: <b style="color:${total.answered ? pcolor(total.pct) : '#94a3b8'}">${total.answered ? total.pct + '%' : '—'}</b></span>
        <button onclick="toggleStepsProblems()" class="px-3 py-1.5 rounded-xl font-semibold ${stepsOnlyProblems ? 'bg-rose-600 text-white' : 'bg-white border border-slate-200 text-slate-700 hover:bg-slate-50'}">Faqat muammoli</button>
      </div>
    </div>
    <div class="flex flex-wrap gap-2">${jump}</div>
    <div>${sections}</div>`;
}

// Ekran kengligi o'zgarsa, qadamlar qator uzunligini qayta hisoblaydi
let stepsResizeTimer = null;
window.addEventListener('resize', () => {
  clearTimeout(stepsResizeTimer);
  stepsResizeTimer = setTimeout(() => { if (wsPane === 'steps' && curCompany()) renderSteps(); }, 150);
});

// ==================== RADAR DIAGRAMMA (kompaniya dashboardi) ====================
let radarMode = 'stages';
function setRadarMode(m) { radarMode = m; renderCompanyDashboard(); }

function radarItems(company) {
  if (radarMode === 'map') {
    return MAP_STAGES.map(ms => ({ label: ms.short, sc: stageMapScore(company, ms.id) }));
  }
  if (radarMode.startsWith('stage_')) {
    const stg = EJM_TEMPLATE.find(x => x.id === radarMode);
    return stg.blocks.map(b => ({ label: b.title.replace(/^\d+\.\d+\s*/, ''), sc: scoreOfCodes(company, b.questions.map(q => q.code)) }));
  }
  return EJM_TEMPLATE.map(stg => ({
    label: stg.shortName.replace(/^\d+\.\s*/, ''),
    sc: scoreOfCodes(company, stg.blocks.flatMap(b => b.questions.map(q => q.code)))
  }));
}

function radarSvg(items) {
  const n = items.length;
  const W = 640, H = 440, cx = W / 2, cy = H / 2 + 6, R = 150;
  const ang = i => -Math.PI / 2 + (2 * Math.PI * i) / n;
  const pt = (i, r) => [cx + r * Math.cos(ang(i)), cy + r * Math.sin(ang(i))];
  const poly = r => items.map((_, i) => pt(i, r).map(v => v.toFixed(1)).join(',')).join(' ');
  let g = '';
  [20, 40, 60, 80, 100].forEach(l => {
    g += `<polygon points="${poly(R * l / 100)}" fill="none" stroke="#e5e7eb" stroke-width="1.5"/>`;
  });
  items.forEach((_, i) => { const [x, y] = pt(i, R); g += `<line x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}" stroke="#eef0f4"/>`; });
  [20, 60, 100].forEach(l => { g += `<text x="${cx + 4}" y="${(cy - R * l / 100 + 11).toFixed(1)}" font-size="9" fill="#9ca3af">${l}</text>`; });
  const vals = items.map(it => (it.sc.answered ? it.sc.pct : 0));
  g += `<polygon points="${items.map((_, i) => pt(i, R * vals[i] / 100).map(v => v.toFixed(1)).join(',')).join(' ')}" fill="#2563eb" fill-opacity="0.18" stroke="#2563eb" stroke-width="2.5" stroke-linejoin="round"/>`;
  items.forEach((it, i) => {
    const [x, y] = pt(i, R * vals[i] / 100);
    const has = it.sc.answered > 0;
    g += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="5" fill="${has ? pcolor(vals[i]) : '#fff'}" stroke="${has ? '#fff' : '#9ca3af'}" stroke-width="2"><title>${escapeHtml(it.label)}: ${has ? vals[i] + '%' : 'javob yo‘q'}</title></circle>`;
    const [lx, ly] = pt(i, R + 22);
    const c = Math.cos(ang(i));
    const anchor = Math.abs(c) < 0.25 ? 'middle' : c > 0 ? 'start' : 'end';
    const short = it.label.length > 24 ? it.label.slice(0, 23) + '…' : it.label;
    g += `<text x="${lx.toFixed(1)}" y="${(ly + 4).toFixed(1)}" font-size="11" font-weight="600" fill="#334155" text-anchor="${anchor}">${escapeHtml(short)}<tspan x="${lx.toFixed(1)}" dy="13" font-size="10" font-weight="800" fill="${has ? pcolor(vals[i]) : '#9ca3af'}">${has ? vals[i] + '%' : '—'}</tspan></text>`;
  });
  return `<svg viewBox="0 0 ${W} ${H}" class="w-full max-w-[640px] mx-auto" role="img" aria-label="Tizim profili radar diagrammasi">${g}</svg>`;
}

function radarCard(company) {
  const items = radarItems(company);
  const answered = items.filter(i => i.sc.answered);
  let note = '';
  if (answered.length >= 2) {
    const sorted = [...answered].sort((a, b) => a.sc.pct - b.sc.pct);
    const lo = sorted[0], hi = sorted[sorted.length - 1];
    note = `<div class="text-xs text-slate-500 text-center">Eng kuchli: <b class="text-emerald-600">${escapeHtml(hi.label)} (${hi.sc.pct}%)</b> • Eng zaif: <b class="text-rose-600">${escapeHtml(lo.label)} (${lo.sc.pct}%)</b> • Farq: <b>${hi.sc.pct - lo.sc.pct}</b> punkt</div>`;
  }
  const tab = (id, label) => `<button type="button" onclick="setRadarMode('${id}')" class="px-3 py-1.5 rounded-lg text-xs font-bold ${radarMode === id ? 'bg-brand-600 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}">${label}</button>`;
  const blockSel = `<select onchange="setRadarMode(this.value)" class="px-2.5 py-1.5 rounded-lg text-xs font-bold border ${radarMode.startsWith('stage_') ? 'border-brand-600 text-brand-700 bg-brand-50' : 'border-slate-200 text-slate-700 bg-white'}">
    <option value="" ${radarMode.startsWith('stage_') ? '' : 'selected'} disabled>Bloklar bo‘yicha…</option>
    ${EJM_TEMPLATE.map(stg => `<option value="${stg.id}" ${radarMode === stg.id ? 'selected' : ''}>${escapeHtml(stg.shortName)} — bloklar</option>`).join('')}</select>`;
  return `
    <div class="p-5 rounded-2xl bg-white border border-slate-200 shadow-sm space-y-2">
      <div class="flex flex-wrap items-start justify-between gap-3">
        <div><h3 class="text-base font-bold text-slate-900">Tizim profili</h3>
          <p class="text-xs text-slate-500">Radar diagrammasi bo‘limlar orasidagi nomutanosiblikni ko‘rsatadi.</p></div>
        <div class="flex flex-wrap items-center gap-1.5">${tab('stages', 'Audit bosqichlari')}${tab('map', 'EJM xaritasi')}${blockSel}</div>
      </div>
      ${radarSvg(items)}
      ${note}
    </div>`;
}

function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}
  
